export function CouponField({
  appliedCode,
  pending = false,
  onApply,
}: CouponFieldProps) {
  const [value, setValue] = useState("");

  function apply() {
    const code = normalizeCouponCode(value);
    if (code) onApply(code);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key !== "Enter") return;
